import { after, before, describe, it } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { http, HttpResponse } from 'msw'
import { setupServer } from 'msw/node'
import { createApp } from '../src/app.mjs'
import { createPricingClient } from '../src/pricing-client.mjs'

const prices = { A: 10, B: 50, C: 19.99, D: 101, E: 0.1 }
const mock = setupServer(
  http.get('http://pricing.test/prices/:sku', ({ params }) => HttpResponse.json({ price: prices[params.sku] })),
)

let server, base
before(async () => {
  mock.listen({ onUnhandledRequest: 'error' })
  server = createServer(createApp({ pricing: createPricingClient('http://pricing.test') }))
  await new Promise((r) => server.listen(0, '127.0.0.1', r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => { mock.close(); server.close() })

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

describe('POST /orders totals', () => {
  it('returns 201 with id, items and total', async () => {
    const res = await post({ items: [{ sku: 'A', qty: 2 }] })
    assert.equal(res.status, 201)
    assert.match(res.headers.get('content-type'), /application\/json/)
    const body = await res.json()
    assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
    assert.equal(typeof body.id, 'string')
    assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }])
    assert.equal(body.total, 20)
  })
  it('sums several lines without discount at or below 100', async () => {
    assert.equal(await totalOf([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }]), 60)
  })
  it('gives no discount at exactly 100', async () => {
    assert.equal(await totalOf([{ sku: 'B', qty: 2 }]), 100)
  })
  it('applies 10% above 100 (150 -> 135)', async () => {
    assert.equal(await totalOf([{ sku: 'B', qty: 3 }]), 135)
  })
  it('floors the discounted total (101 -> 90.9 -> 90)', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — total is truncated to whole euros, so cents are lost (90.9 becomes 90)
    assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 90)
  })
  it('floors fractional undiscounted totals (19.99*3 = 59.97 -> 59)', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — cents are dropped even without discount
    assert.equal(await totalOf([{ sku: 'C', qty: 3 }]), 59)
  })
  it('floors large discounted fractional totals (19.99*6 = 119.94 -> 107.946 -> 107)', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — discount on larger orders is floored, never rounded; also float arithmetic
    assert.equal(await totalOf([{ sku: 'C', qty: 6 }]), 107)
  })
  it('applies a flat 10% to arbitrarily large orders (no tiers)', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — no bigger discount for bigger orders
    assert.equal(await totalOf([{ sku: 'B', qty: 100 }]), 4500)
  })
  it('floors a sub-euro total to 0', async () => {
    assert.equal(await totalOf([{ sku: 'E', qty: 5 }]), 0)
  })
  it('accepts a negative qty and lets it reduce the total', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — qty is not validated
    assert.equal(await totalOf([{ sku: 'B', qty: -1 }]), -50)
  })
})

describe('POST /orders validation', () => {
  for (const [name, body, raw] of [
    ['missing items', {}],
    ['empty items', { items: [] }],
    ['non-array items', { items: 'x' }],
    ['invalid JSON', null, '{nope'],
  ]) {
    it(`returns 400 for ${name}`, async () => {
      const res = await post(body, raw)
      assert.equal(res.status, 400)
      assert.deepEqual(await res.json(), { error: 'items required' })
    })
  }
})

describe('GET /orders/:id', () => {
  it('returns a created order', async () => {
    const created = await (await post({ items: [{ sku: 'B', qty: 3 }] })).json()
    const res = await fetch(`${base}/orders/${created.id}`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), created)
  })
  it('returns 200 with an error body for an unknown id', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — missing order answers 200, not 404
    const res = await fetch(`${base}/orders/does-not-exist`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), { error: 'not found' })
  })
})

describe('unknown routes', () => {
  it('returns 404 no route', async () => {
    for (const [method, path] of [['GET', '/nope'], ['PUT', '/orders'], ['DELETE', '/orders/1'], ['GET', '/orders']]) {
      const res = await fetch(base + path, { method })
      assert.equal(res.status, 404, `${method} ${path}`)
      assert.deepEqual(await res.json(), { error: 'no route' })
    }
  })
})
EOF
